// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] calldata _tos, uint v, uint _decimals) public {
        // Ensure the call will not revert due to require(_tos.length > 0)
        vm.assume(_tos.length > 0);
        // Bound _decimals to a reasonable range to avoid overflow in multiplication
        // (v * 10**_decimals could overflow; bounded to avoid unrealistic fuzz)
        _decimals = bound(_decimals, 0, 36);
        v = bound(v, 0, type(uint).max / 10**_decimals); // ensure v * 10**_decimals does not overflow

        bool success;
        bool result;
        // Use try/catch to catch revert
        try c.transfer(from, caddress, _tos, v, _decimals) returns (bool r) {
            success = true;
            result = r;
        } catch {
            success = false;
        }
        // If call succeeds (does not revert), the return value must be true
        assertTrue(!success || result);
    }
}

